// Nur echte Zahlen-IDs annehmen, höchstens 40 auf einmal (Kostenbremse)
let b = $('Start von der Seite').first().json.body || {};
if (typeof b === 'string') {
  try {
    b = JSON.parse(b);
  } catch (e) {
    b = {};
  }
}
const ids = [...new Set((Array.isArray(b.ids) ? b.ids : []).map(Number).filter((x) => Number.isInteger(x) && x > 0))].slice(0, 40);
const zeilen = {};
for (const i of $('Alle Stellen laden').all()) if (i.json.id) zeilen[i.json.id] = { ...i.json };
for (const i of $('Meine Notizen laden').all()) {
  const z = zeilen[i.json.job_id];
  if (z) Object.assign(z, { meine_notiz: i.json.notiz || '', meine_tendenz: i.json.tendenz || '' });
}
// Bereich je Stelle schickt die Seite mit (für den passenden Lebenslauf)
const bereich = {};
for (const s of Array.isArray(b.stellen) ? b.stellen : []) bereich[Number(s.id)] = String(s.bereich || '').slice(0, 80);
const aus = ids.filter((id) => zeilen[id]).map((id) => ({ json: { ...zeilen[id], _bereich: bereich[id] || '' } }));
return aus.length ? aus : [{ json: { _leer: true } }];

const row = $('Schleife: eine Stelle nach der anderen').first().json;
const cache = $('Seitentext aus Cache').first().json;
const p = $('Profil laden').first().json || {};
// Lebenslauf des Bereichs der Stelle (Zeilen aus den Einstellungen); was dort fehlt, ersetzt der Standard
const lebenslaufFuer = (bereich, en) => {
  const w = String(bereich || '').trim().toLowerCase();
  const z = w ? (p.lebenslaeufe || []).find((x) => String(x.bereich || '').trim().toLowerCase() === w) : null;
  const reihe = en ? [z && z.text_en, p.lebenslauf_en_text, z && z.text_de, p.lebenslauf_text] : [z && z.text_de, p.lebenslauf_text];
  return reihe.find(Boolean) || '';
};
const vorlage = String($('Tiefencheck-Prompt laden').first().json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [standard, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
// Eigene Prüf-Anweisungen (⚙️ Einstellungen → 🔍 Tiefen-Check) ersetzen nur den System-Teil – Anfrage und Antwort-Schema bleiben fest
const system = String(p.tiefencheck_prompt || '').trim() || standard;
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, key) => (key in werte ? werte[key] : m));
const fakten = [
  `Jobtitel: ${row.jobtitel || '-'}`, `Firma: ${row.firma || '-'}`, `Ort: ${row.ort || '-'}`, `Remote: ${row.remote || '-'}`,
  `Remote-Regel (wörtlich): ${row.remote_regel_wortlaut || '-'}`, `Gehalt: ${row.gehalt || '-'}`, `Vertragsform: ${row.vertragsform || '-'}`,
  `Bewerbungsweg: ${row.bewerbungsweg || '-'}`, `Veröffentlicht: ${row.veroeffentlichungsdatum || 'unbekannt'}`, `URL: ${row.url}`,
].join('\n');
const bewertung = `Score ${row.passung_score || '-'} (${row.bewertung || '-'}): ${String(row.bewertung_begruendung || '').replace(/\s*\[[^\]]*\]/g, '')}\nOffene Fragen: ${row.offene_fragen || '-'}`;
const liste = (beschreibung, props, req) => ({ type: 'array', description: beschreibung, items: { type: 'object', additionalProperties: false, required: req, properties: props } });
const s = (d) => ({ type: 'string', description: d });
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['aufgaben_vergleich', 'empfehlung', 'kurzfazit', 'klartext', 'anforderungen', 'remote_einschaetzung', 'firma', 'warnsignale', 'argumente', 'fragen', 'unterlagen'],
  properties: {
    unterlagen: {
      type: 'object',
      additionalProperties: false,
      required: ['anschreiben', 'lebenslauf', 'video', 'portfolio', 'hinweis'],
      description: 'Was die Firma für die Bewerbung haben will – nur, was in der Anzeige steht',
      properties: {
        anschreiben: { type: 'string', enum: ['gefragt', 'nicht_noetig', 'unklar'], description: 'gefragt = Anschreiben/Cover Letter verlangt oder Feld dafür; nicht_noetig = Anzeige sagt ausdrücklich, dass keins nötig ist; sonst unklar' },
        lebenslauf: { type: 'boolean' },
        video: { type: 'boolean', description: 'Video-Vorstellung verlangt oder erwünscht' },
        portfolio: { type: 'boolean', description: 'Portfolio, GitHub-Profil, Arbeitsproben oder Referenzen verlangt/erwünscht' },
        hinweis: s('Kurz, was sonst verlangt ist (z. B. "Fragen im Formular", "Gehaltsvorstellung", "englischer CV") oder ""'),
      },
    },
    aufgaben_vergleich: {
      type: 'object',
      additionalProperties: false,
      required: ['bezug_suchprompt', 'urteil'],
      properties: {
        bezug_suchprompt: s('Welche Aussage aus dem Such-Prompt betrifft diese Rolle? Sinngemäß, in Du-Form, 1 Satz (z. B. "Du hast geschrieben, dass du auch Vertrieb machst, wenn es zu deinen Skills passt.")'),
        urteil: s('2–3 Sätze: Passen die konkreten Aufgaben und Anforderungen der Stelle zu dem, was du laut Lebenslauf kannst? Klar sagen, ob es noch in deinem Bereich liegt oder weit mehr verlangt (und was genau)'),
      },
    },
    empfehlung: { type: 'string', enum: ['unbedingt_bewerben', 'probier_es', 'erwarte_nichts'], description: 'unbedingt_bewerben = passt sehr gut; probier_es = Chance da, aber Lücken/offene Punkte; erwarte_nichts = verlangt deutlich mehr/anderes, nur bewerben wenn Zeit übrig' },
    kurzfazit: s('GENAU EIN kurzer Satz in Du-Form, z. B. "Die Stelle kann passen, wenn …" oder "Passt, weil …" oder "Eher nicht, weil …". Max. 25 Wörter'),
    klartext: liste('Buzzwords → Klartext, max. 6', { begriff: s('wörtlich aus der Anzeige'), bedeutet: s('Klartext') }, ['begriff', 'bedeutet']),
    anforderungen: liste('Anforderungen gegen Lebenslauf, max. 10', { anforderung: s('Anforderung'), status: { type: 'string', enum: ['erfuellt', 'teilweise', 'fehlt'] }, beleg: s('kurzer Beleg aus dem Lebenslauf') }, ['anforderung', 'status', 'beleg']),
    remote_einschaetzung: s('Wie realistisch ist ortsunabhängiges Arbeiten von überall (ohne festen Wohnsitz, wechselnde Länder)? Mit Zitat aus der Anzeige'),
    firma: s('Was man über die Firma weiß – Fremdwissen als (KI-Wissen, ungeprüft) markieren'),
    warnsignale: s('Warnsignale oder "keine"'),
    argumente: { type: 'array', items: { type: 'string' }, description: 'Die 3 stärksten Argumente für eine Bewerbung' },
    fragen: { type: 'array', items: { type: 'string' }, description: '3–5 Fragen fürs erste Gespräch' },
  },
};
return [
  {
    json: {
      system,
      anfrage: fuellen(anfrage, {
        HEUTE: $now.toFormat('yyyy-MM-dd'),
        KRITERIEN: p.kriterien || '(kein Such-Prompt hinterlegt)',
        LEBENSLAUF: lebenslaufFuer(row._bereich, false) || '(kein Lebenslauf hochgeladen)',
        FAKTEN: fakten,
        BEWERTUNG: bewertung,
        NOTIZ: `Tendenz: ${row.meine_tendenz || '-'}\nNotiz: ${String(row.meine_notiz || '').trim() || '(keine)'}`,
        SEITENTEXT: '{{SEITENTEXT}}',
      }),
      seitentext: cache && cache.ok ? String(cache.text) : '(kein Seitentext im Cache – nur Fakten verwenden)',
      schema: SCHEMA,
      funktion: 'tiefencheck', // Modell laut ⚙️ Einstellungen
      claude_effort_override: 'medium',
      ollama_denken_override: 'an',
      kontext: { id: row.id },
    },
  },
];

const r = $json;
const id = r.kontext && r.kontext.id;
const jetzt = new Date().toISOString();
if (!r.ok) return [{ json: { job_id: id, ampel: 'fehler', ergebnis: JSON.stringify({ fehler: r.fehler || 'keine Antwort' }), modell: `${r.anbieter}:${r.modell}`, geprueft_am: jetzt } }];
// Ampel für Tabelle/Listen aus der Empfehlung ableiten
const AMPEL = { unbedingt_bewerben: 'gruen', probier_es: 'gelb', erwarte_nichts: 'rot' };
return [{ json: { job_id: id, ampel: AMPEL[r.daten.empfehlung] || String(r.daten.ampel || ''), ergebnis: JSON.stringify(r.daten), modell: `${r.anbieter}:${r.modell}`, geprueft_am: jetzt } }];
